// blockDim.x = 256; input `x`, output `y` (both length 256)
__global__ void shifted_add(const float* x, float* y) {
    __shared__ float smem[256];
    int tid = threadIdx.x;
    smem[tid] = x[tid];
    // (missing __syncthreads() here?)
    if (tid == 0) y[tid] = smem[tid];
    else          y[tid] = smem[tid - 1] + smem[tid];
}
